practice.starterCode:
CREATE TABLE tx12_accounts (account_id INTEGER PRIMARY KEY, balance INTEGER NOT NULL CHECK (balance >= 0));
INSERT INTO tx12_accounts VALUES (1, 100), (2, 100);
BEGIN;
UPDATE tx12_accounts SET balance = balance - 25 WHERE account_id = 1;
UPDATE tx12_accounts SET balance = balance + 25 WHERE account_id = 2;
COMMIT;
SELECT account_id, balance FROM tx12_accounts ORDER BY account_id;

